window.CAGE_COLLAB={capture:()=>({...prefs}),restoreView,async open(view,id){setView(view);await load();if(!id)return;if(view==='notices')await noticeDetail(id);else await eventDetail(id);},async restore(saved){await load();const mode=saved.forms?.some(f=>f.id==='hub-notice-form')?'edit':saved.forms?.some(f=>f.id==='hub-event-form')?'edit':saved.forms?.some(f=>f.id==='hub-occurrence-form')?'occurrence':'detail';const record=saved.hubRecord||'';if(saved.id==='hub-notice-dialog'){if(mode==='edit')editNotice(saved.forms?.find(f=>f.id==='hub-notice-form')?.data?.id||record);else await noticeDetail(record);}else{await refreshCalendar();if(mode==='edit'){const id=saved.forms?.find(f=>f.id==='hub-event-form')?.data?.id;if(id){const raw=await api().hubEvent(id);eventForm({key:record,raw});}else eventForm();}else if(mode==='occurrence'){let e=lookup(record);if(!e)throw Error('Return to this occurrence in the calendar to reopen its draft.');editOccurrence(e);}else await eventDetail(record);}},test:{range,local,utc,layoutTimes,formatted,sourceItems}};
